// src/renderer/colorBits.ts
function packAbgr(r, g, b, a) {
  return (a << 24 | b << 16 | g << 8 | r) >>> 0;
}
function abgrRed(c) {
  return c & 255;
}
function abgrGreen(c) {
  return c >>> 8 & 255;
}
function abgrBlue(c) {
  return c >>> 16 & 255;
}
function abgrAlpha(c) {
  return c >>> 24 & 255;
}
function abgrToCssRgba(c) {
  return `rgba(${abgrRed(c)},${abgrGreen(c)},${abgrBlue(c)},${abgrAlpha(c) / 255})`;
}
function normalizedRgbToCssRgba(c, alpha) {
  return `rgba(${Math.round(c[0] * 255)},${Math.round(c[1] * 255)},${Math.round(c[2] * 255)},${alpha})`;
}
function fadeAbgr(c, alpha) {
  return packAbgr(
    abgrRed(c),
    abgrGreen(c),
    abgrBlue(c),
    Math.round(abgrAlpha(c) * alpha)
  );
}
function brightenAbgr(c, factor) {
  const t = Math.max(0, 1 - 1 / factor);
  const lift = (v) => Math.round(v + (255 - v) * t);
  return packAbgr(
    lift(abgrRed(c)),
    lift(abgrGreen(c)),
    lift(abgrBlue(c)),
    abgrAlpha(c)
  );
}

export {
  packAbgr,
  abgrRed,
  abgrGreen,
  abgrBlue,
  abgrAlpha,
  abgrToCssRgba,
  normalizedRgbToCssRgba,
  fadeAbgr,
  brightenAbgr
};
